                for (var t = (night - 1) * Time.DAY_LENGTH; t < ((night * Time.DAY_LENGTH) + Time.DAY_LENGTH); t++)
                {
                    if (Zombies.isSpawnTick(t) && (Time.nightNumber(t) == night))
